values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'about-mosaic', 'About with photo mosaic', '{"eyebrow":"Our Story","title":"A Little More Hope.","accent":"A Lot More Care.","link":{"label":"About us","href":"/about"},"badge":"One-to-one consultations","mainImage":{"src":"/themes/bloom/couple-ultrasound.jpg","alt":"Couple holding their baby''s first ultrasound photo"},"statImage":{"src":"/themes/bloom/family-joy.jpg","alt":"Happy family"},"secondImage":{"src":"/themes/bloom/doctor-consultation.jpg","alt":"Fertility doctor in a consultation with a patient"},"thirdImage":{"src":"/themes/bloom/pregnant-belly.jpg","alt":"Expecting mother cradling her belly"},"firstStat":{"value":"2,500+","label":"Happy Families"},"secondStat":{"value":"15+","label":"Years of Care"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"link":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false},"badge":{"type":"string","minLength":1,"maxLength":200},"mainImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"secondImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"thirdImage":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"statImage":{"type":"object","properties":{"src":{"type":"string","maxLen