values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'expanding-cards', 'Expanding photo cards', '{"eyebrow":"Our Treatments","title":"Personalised Paths","accent":"To Parenthood.","items":[{"title":"IVF Treatment","description":"Advanced fertility care, personalized for your journey.","tag":"Advanced Care","image":{"src":"/themes/bloom/ivf.jpg","alt":"IVF treatment"},"href":"/treatments"},{"title":"IUI Treatment","description":"A supportive approach to your fertility journey.","tag":"Personalized Care","image":{"src":"/themes/bloom/iui.jpg","alt":"IUI treatment"},"href":"/treatments"},{"title":"Fertility Assessment","description":"Understand your fertility with expert guidance.","tag":"Your First Step","image":{"src":"/themes/bloom/fertility-assessment.jpg","alt":"Fertility assessment"},"href":"/treatments"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":2,"maxItems":5,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"description":{"type":"string","minLength":1,"maxLength":2000},"tag":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 130);
