values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'specialists', 'Specialist cards', '{"eyebrow":"Meet Our Specialists","title":"Expertise That Makes","accent":"Every Journey Personal.","link":"/contact","members":[{"name":"Dr. Ananya Sharma","role":"Senior Fertility Specialist","experience":"15+ Years Experience","image":{"src":"/themes/bloom/doctor-1.jpg","alt":"Dr. Ananya Sharma"}},{"name":"Dr. Rohan Mehta","role":"IVF & Reproductive Specialist","experience":"12+ Years Experience","image":{"src":"/themes/bloom/doctor-2.jpg","alt":"Dr. Rohan Mehta"}},{"name":"Dr. Priya Verma","role":"Reproductive Medicine Expert","experience":"10+ Years Experience","image":{"src":"/themes/bloom/doctor-3.jpg","alt":"Dr. Priya Verma"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"link":{"type":"string","maxLength":2048},"members":{"minItems":1,"maxItems":24,"type":"array","items":{"type":"object","properties":{"name":{"type":"string","minLength":1,"maxLength":200},"role":{"type":"string","minLength":1,"maxLength":200},"experience":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["name","image"],"additionalProperties":false}}},"required":["title","members"],"additionalProperties":false}'::jsonb, 150);
