values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'photo-strips', 'Moving photo strips', '{"eyebrow":"Moments of Joy","title":"Little Miracles,","accent":"Big Happiness.","images":[{"src":"/themes/bloom/parents-baby.jpg","alt":"Parents hugging their smiling toddler"},{"src":"/themes/bloom/baby-hand.jpg","alt":"Newborn holding a parent''s finger"},{"src":"/themes/bloom/sari-maternity.jpg","alt":"Expecting mother in a traditional sari"},{"src":"/themes/bloom/mother-baby.jpg","alt":"Mother carrying her baby"},{"src":"/themes/bloom/baby-feet.jpg","alt":"Parent cradling a newborn''s feet"},{"src":"/themes/bloom/smiling-baby.jpg","alt":"Mother holding a smiling baby"},{"src":"/themes/bloom/touching-belly.jpg","alt":"Couple''s hands on a pregnant belly"},{"src":"/themes/bloom/baby-portrait.jpg","alt":"Baby with wide curious eyes"},{"src":"/themes/bloom/infant-feet-henna.jpg","alt":"Mother holding her infant''s feet"},{"src":"/themes/bloom/carrying-baby.jpg","alt":"Woman carrying her baby at home"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"images":{"minItems":4,"maxItems":24,"type":"array","items":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}}},"required":["title","images"],"additionalProperties":false}'::jsonb, 160);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'photo-rows', 'Alternating photo rows', '{"eyebrow":"What We Offer","title":"Care For Every","accent":"Kind Of Journey.","items":[{"title":"IVF Treatment","tagline":"Advanced Care","summary":"Eggs and sperm are brought together in our lab, and a healthy embryo is placed back in the uterus.","image":{"src":"/themes/bloom/ivf.jpg","alt":"IVF treatment"},"href":"/contact"},{"title":"ICSI Treatment","tagline":"Precision Science","summary":"A single healthy sperm is injected directly into each egg, giving fertilisation the best chance.","image":{"src":"/themes/bloom/lab-technology.jpg","alt":"Embryology laboratory"},"href":"/contact"},{"title":"IUI Treatment","tagline":"Gentle First Step","summary":"Prepared sperm is placed directly in the uterus at the time of ovulation — simple and low-stress.","image":{"src":"/themes/bloom/iui.jpg","alt":"IUI treatment"},"href":"/contact"},{"title":"Fertility Assessment","tagline":"Your First Step","summary":"A complete check-up for both partners so we understand your fertility and plan the right path.","image":{"src":"/themes/bloom/fertility-assessment-image.jpg","alt":"Fertility assessment"},"href":"/contact"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":10,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"tagline":{"type":"string","minLength":1,"maxLength":200},"summary":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"href":{"type":"string","maxLength":2048}},"required":["title","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 170);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'stories', 'Photo stories', '{"eyebrow":"Our Families","title":"Journeys That","accent":"Ended In Joy.","items":[{"names":"Priya & Rahul","place":"Pune","tag":"IVF","quote":"After years of waiting, the team made us feel hopeful again.","image":{"src":"/themes/bloom/parents-baby.jpg","alt":"Parents with their baby"}},{"names":"Sneha & Arvind","place":"Bengaluru","tag":"ICSI","quote":"Every question was answered with patience and kindness.","image":{"src":"/themes/bloom/mother-baby.jpg","alt":"Mother carrying her baby"}},{"names":"Kavya","place":"Mumbai","tag":"IUI","quote":"Simple, gentle and so caring — exactly what we needed.","image":{"src":"/themes/bloom/sari-maternity.jpg","alt":"Expecting mother in a sari"}},{"names":"Anjali & Vikram","place":"Delhi","tag":"IVF","quote":"They celebrated every small milestone with us.","image":{"src":"/themes/bloom/smiling-baby.jpg","alt":"Mother holding a smiling baby"}},{"names":"Meera & Karan","place":"Jaipur","tag":"Fertility Assessment","quote":"Clear answers in one visit took away so much stress.","image":{"src":"/themes/bloom/baby-hand.jpg","alt":"Newborn holding a parent''s finger"}},{"names":"Ritu & Sameer","place":"Hyderabad","tag":"ICSI","quote":"Our little one is here because they never gave up.","image":{"src":"/themes/bloom/carrying-baby.jpg","alt":"Woman carrying her baby"}}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"items":{"minItems":1,"maxItems":18,"type":"array","items":{"type":"object","properties":{"names":{"type":"string","minLength":1,"maxLength":200},"place":{"type":"string","minLength":1,"maxLength":200},"tag":{"type":"string","minLength":1,"maxLength":200},"quote":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false}},"required":["names","quote","image"],"additionalProperties":false}}},"required":["title","items"],"additionalProperties":false}'::jsonb, 180);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'mission-vision', 'Mission, vision and values', '{"title":"Mission & Vision.","pillars":[{"label":"Our Mission","title":"Care That Feels Personal","text":"To give every family honest guidance, advanced treatment and steady support at every step.","icon":"target","image":{"src":"/themes/bloom/doctor-consultation.jpg","alt":"Fertility specialist talking with a couple"}},{"label":"Our Vision","title":"A Family For Everyone","text":"To be the most trusted fertility home, where science and compassion make parenthood possible.","icon":"eye","image":{"src":"/themes/bloom/family-joy.jpg","alt":"Happy family holding their baby"}}],"values":[{"title":"Compassion","text":"Every patient treated like family.","icon":"hand-heart"},{"title":"Integrity","text":"Clear advice and honest pricing.","icon":"shield-check"},{"title":"Innovation","text":"Modern labs and proven methods.","icon":"lightbulb"},{"title":"Partnership","text":"We decide together, always.","icon":"users"}]}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"pillars":{"minItems":1,"maxItems":2,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":2000},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"icon":{"type":"string","enum":["heart-handshake","microscope","user-check","hand-heart","shield-check","lightbulb","users","target","eye","heart","sparkles"]}},"required":["label","title","text","image","icon"],"additionalProperties":false}},"values":{"maxItems":8,"type":"array","items":{"type":"object","properties":{"title":{"type":"string","minLength":1,"maxLength":200},"text":{"type":"string","minLength":1,"maxLength":200},"icon":{"type":"string","enum":["heart-handshake","microscope","user-check","hand-heart","shield-check","lightbulb","users","target","eye","heart","sparkles"]}},"required":["title","text","icon"],"additionalProperties":false}}},"required":["title","pillars","values"],"additionalProperties":false}'::jsonb, 190);
insert into public.theme_sections (theme_version_id, section_type, label, default_props, props_schema, display_order)
values ((select v.id from public.theme_versions v join public.themes t on t.id = v.theme_id where t.slug = 'bloom' and v.version = '1.0.0'), 'photo-banner', 'Full photo banner', '{"eyebrow":"Your Story Starts Here","title":"Your Journey","accent":"Starts Here.","image":{"src":"/themes/bloom/baby-hand-cta.jpg","alt":"Newborn''s hand resting in a parent''s palm"},"button":{"label":"Book Consultation","href":"/contact"}}'::jsonb, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"eyebrow":{"type":"string","minLength":1,"maxLength":200},"title":{"type":"string","minLength":1,"maxLength":200},"accent":{"type":"string","minLength":1,"maxLength":200},"image":{"type":"object","properties":{"src":{"type":"string","maxLength":2048},"alt":{"type":"string","maxLength":200}},"required":["src","alt"],"additionalProperties":false},"button":{"type":"object","properties":{"label":{"type":"string","minLength":1,"maxLength":60},"href":{"type":"string","maxLength":2048}},"required":["label","href"],"additionalProperties":false}},"required":["title","image"],"additionalProperties":false}'::jsonb, 200);

insert into public.templates (theme_id, name, slug, description, status, is_featured)
select id, name, slug, description, 'published', is_featured from public.themes where slug = 'bloom';

insert into public.template_categories (template_id, category_id)
select t.id, c.id
from public.templates t
cross join public.categories c
where t.slug = 'bloom' and c.slug in ('ivf-center', 'medical-clinic', 'hospital');
